// Smallest per-level stash (a multiple of 64 slots) whose single-level
// overflow bound is <= target_log2 (<= 0).  Returns 0 if none in range.
inline unsigned LevelStashSlots(double n_events, double target_log2) {
  const double strict = -target_log2;
  int e = static_cast<int>(strict);
  if (strict > static_cast<double>(e)) ++e;  // ceil: round to stricter
  if (e < kStashCapMinExp) e = kStashCapMinExp;
  if (e > kStashCapMaxExp) return 0;  // lifetime too strict for the table
  const uint64_t need = static_cast<uint64_t>(std::ceil(n_events));
  const int col = e - kStashCapMinExp;
  for (unsigned s = 1; s <= kStashCapMaxBuckets; ++s) {
    if (need <= kStashCapMaxEvents[s - 1][col]) return s * 64u;
  }
  return 0;
}

